def doc(x,y,w=112,h=140,fill=C):return f'<g transform="translate({x} {y})">'+rect(5,6,w,h,L)+path(f'M0 0H{w-25}L{w} 25V{h}H0Z',fill)+path(f'M{w-25} 0V25H{w}')+line(18,48,w-18,48)+line(18,64,w-29,64)+line(18,80,w-22,80)+'</g>'
